Here is the commit message:
cpufreq: governor: fix double free in
 cpufreq_dbs_governor_init() error path

When kobject_init_and_add() fails, cpufreq_dbs_governor_init() calls
kobject_put(&dbs_data->attr_set.kobj).

The kobject release callback cpufreq_dbs_data_release() calls
gov->exit(dbs_data) and kfree(dbs_data), but the current error path
then calls gov->exit(dbs_data) and kfree(dbs_data) again, causing a
double free.

Keep the direct kfree(dbs_data) for the gov->init() failure path, but
after kobject_init_and_add() has been called, let kobject_put() handle
the cleanup through cpufreq_dbs_data_release().

Fixes: 4ebe36c94aed ("cpufreq: Fix kobject memleak")
Signed-off-by: Guangshuo Li <lgs201920130244@gmail.com>
Reviewed-by: Zhongqiu Han <zhongqiu.han@oss.qualcomm.com>
Acked-by: Viresh Kumar <viresh.kumar@linaro.org>
Cc: All applicable <stable@vger.kernel.org>
Link: https://patch.msgid.link/20260401024535.1395801-1-lgs201920130244@gmail.com
Signed-off-by: Rafael J. Wysocki <rafael.j.wysocki@intel.com>

Here is the root cause:
After kobject_init_and_add() fails, kobject_put() is called which triggers the release callback cpufreq_dbs_data_release() that frees dbs_data and calls gov->exit(). However, the error path subsequently also calls gov->exit(dbs_data) and kfree(dbs_data) again, causing a double free.

Here is the patch:

 int cpufreq_dbs_governor_init(struct cpufreq_policy *policy)
 {
 	struct dbs_governor *gov = dbs_governor_of(policy);
 	struct dbs_data *dbs_data;
 	struct policy_dbs_info *policy_dbs;
 	int ret = 0;

 	/* State should be equivalent to EXIT */
 	if (policy->governor_data)
 		return -EBUSY;

 	policy_dbs = alloc_policy_dbs_info(policy, gov);
 	if (!policy_dbs)
 		return -ENOMEM;

 	/* Protect gov->gdbs_data against concurrent updates. */
 	mutex_lock(&gov_dbs_data_mutex);

 	dbs_data = gov->gdbs_data;
 	if (dbs_data) {
 		if (WARN_ON(have_governor_per_policy())) {
 			ret = -EINVAL;
 			goto free_policy_dbs_info;
 		}
 		policy_dbs->dbs_data = dbs_data;
 		policy->governor_data = policy_dbs;

 		gov_attr_set_get(&dbs_data->attr_set, &policy_dbs->list);
 		goto out;
 	}

 	dbs_data = kzalloc_obj(*dbs_data);
 	if (!dbs_data) {
 		ret = -ENOMEM;
 		goto free_policy_dbs_info;
 	}

 	dbs_data->gov = gov;
 	gov_attr_set_init(&dbs_data->attr_set, &policy_dbs->list);

 	ret = gov->init(dbs_data);
 	if (ret)
 		goto free_dbs_data;

 	/*
 	 * The sampling interval should not be less than the transition latency
 	 * of the CPU and it also cannot be too small for dbs_update() to work
 	 * correctly.
 	 */
 	dbs_data->sampling_rate = max_t(unsigned int,
 					CPUFREQ_DBS_MIN_SAMPLING_INTERVAL,
 					cpufreq_policy_transition_delay_us(policy));

 	if (!have_governor_per_policy())
 		gov->gdbs_data = dbs_data;

 	policy_dbs->dbs_data = dbs_data;
 	policy->governor_data = policy_dbs;

 	gov->kobj_type.sysfs_ops = &governor_sysfs_ops;
 	gov->kobj_type.release = cpufreq_dbs_data_release;
 	ret = kobject_init_and_add(&dbs_data->attr_set.kobj, &gov->kobj_type,
 				   get_governor_parent_kobj(policy),
 				   "%s", gov->gov.name);
 	if (!ret)
 		goto out;

 	/* Failure, so roll back. */
 	pr_err("initialization failed (dbs_data kobject init error %d)\n", ret);

-	kobject_put(&dbs_data->attr_set.kobj);
-
 	policy->governor_data = NULL;

 	if (!have_governor_per_policy())
 		gov->gdbs_data = NULL;
-	gov->exit(dbs_data);
+
+	kobject_put(&dbs_data->attr_set.kobj);
+	goto free_policy_dbs_info;

 free_dbs_data:
 	kfree(dbs_data);

 free_policy_dbs_info:
 	free_policy_dbs_info(policy_dbs, gov);

 out:
 	mutex_unlock(&gov_dbs_data_mutex);
 	return ret;
 }
 EXPORT_SYMBOL_GPL(cpufreq_dbs_governor_init);


